def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    aggressive_pressure = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    b = float(bid)
                    prev_bids.append(b)
                    if b >= 120:
                        aggressive_pressure += 1
                except Exception:
                    pass

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.55
    if no_water >= 2:
        danger += 1.0
    elif no_water == 1:
        danger += 0.45
    danger += 0.35 * scarcity

    if danger >= 1.6:
        target = max(95.0, highest_prev + 4.0)
    elif danger >= 0.9:
        target = max(58.0, min(110.0, highest_prev * 0.55 + 8.0))
    else:
        if highest_prev >= 150:
            target = 16.0 + 10.0 * (1.0 - scarcity)
        elif highest_prev >= 90:
            target = 24.0 + 8.0 * (1.0 - scarcity)
        else:
            target = 34.0 + 10.0 * scarcity + 0.08 * avg_prev

    if aggressive_pressure >= 2 and danger < 1.2:
        target *= 0.72

    if day >= 8 and hp >= 6 and no_water == 0:
        target *= 0.85

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if hp > 4:
        reserve_floor = min(budget * 0.6, days_left * 18.0)

    cap = budget - reserve_floor
    if danger >= 1.2:
        cap = budget
    if cap < 0:
        cap = budget * 0.35

    bid = min(budget, cap, target)

    min_live = 8.0
    if danger >= 0.9:
        min_live = 42.0
    elif scarcity > 0.6:
        min_live = 24.0

    bid = max(min_live, bid)
    bid = min(budget, bid)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    HP_THRESHOLD_CRITICAL = 2 
    HP_THRESHOLD_HIGH_PRESSURE = 4 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    opponent_critical_hp_count = 0
    opponent_high_pressure_hp_count = 0

    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

        if opp['hp'] <= HP_THRESHOLD_CRITICAL:
            opponent_critical_hp_count += 1
        elif opp['hp'] <= HP_THRESHOLD_HIGH_PRESSURE:
            opponent_high_pressure_hp_count += 1

    bid = DAILY_SALARY * 0.55 

    if my_status['hp'] <= HP_THRESHOLD_CRITICAL:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= HP_THRESHOLD_HIGH_PRESSURE:
        bid = DAILY_SALARY * 0.8
    else:
        bid = DAILY_SALARY * 0.4 

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        if my_status['hp'] <= HP_THRESHOLD_CRITICAL:
            bid = max(bid, max_prev_bid + 5)
        elif opponent_critical_hp_count > 0:
            bid = max(bid, max_prev_bid + 2)
        elif my_status['hp'] <= HP_THRESHOLD_HIGH_PRESSURE:
            bid = max(bid, max_prev_bid + 1)
        else:
            bid = max(bid, max_prev_bid + 0.5)

    final_bid = min(my_status['budget'], bid)
    final_bid = max(0.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
